{
"sql": "SELECT g.Name AS Genre, SUM(il.UnitPrice * il.Quantity) AS TotalSales FROM Genre g JOIN Track t ON g.GenreId = t.GenreId JOIN InvoiceLine il ON t.TrackId = il.TrackId GROUP BY g.GenreId, g.Name ORDER BY TotalSales DESC LIMIT 5"
}

{
"sql": "SELECT T2.Name, COUNT(DISTINCT T1.GenreId) AS DistinctGenres FROM Track AS T1 JOIN Album AS T2 ON T1.AlbumId = T2.AlbumId GROUP BY T2.ArtistId, T2.Name HAVING COUNT(DISTINCT T1.GenreId) > 3 ORDER BY DistinctGenres DESC"
}

{
"sql": "WITH CustomerSpending AS (SELECT c.CustomerId, c.FirstName, c.LastName, SUM(i.Total) AS TotalSpending FROM Customer c JOIN Invoice i ON c.CustomerId = i.CustomerId GROUP BY c.CustomerId, c.FirstName, c.LastName) SELECT FirstName, LastName, TotalSpending, RANK() OVER (ORDER BY TotalSpending DESC) AS SpendingRank FROM CustomerSpending ORDER BY TotalSpending DESC LIMIT 5;"
}

